from onbellek import onbellekle
import time

# 1. Ayrı fonksiyonların ayrı önbelleği olmalı
@onbellekle()
def f1(x): return x*2
@onbellekle()
def f2(x): return x*3

f1(5); f1(5)
f2(5); f2(5)
print('Ayrı önbellek:', f1.bilgi(), f2.bilgi())
assert f1.bilgi() == {'isabet':1,'iska':1}
assert f2.bilgi() == {'isabet':1,'iska':1}

# 2. TTL testi - tam ttl anında hâlâ geçerli olmalı
@onbellekle(ttl=1, saat=time.monotonic)
def ttl_test(x): return x*10
assert ttl_test(2) == 20
assert ttl_test(2) == 20  # isabet
assert ttl_test.bilgi() == {'isabet':1,'iska':1}

# 3. TTL dolunca yeniden çalışmalı
@onbellekle(ttl=0.01, saat=time.monotonic)
def ttl_expire(x): return x*100
assert ttl_expire(3) == 300
time.sleep(0.02)
assert ttl_expire(3) == 300  # iska tekrar
assert ttl_expire.bilgi() == {'isabet':0,'iska':2}
print('TTL:', ttl_expire.bilgi())

# 4. Hashlenemeyen argüman (liste) - önbelleğe alınmadan çalışmalı
@onbellekle()
def list_arg(x): return sum(x)
assert list_arg([1,2]) == 3
assert list_arg([1,2]) == 3  # her çağrıda iska artmalı
assert list_arg.bilgi() == {'isabet':0,'iska':2}
print('Liste arg:', list_arg.bilgi())

# 5. kwargs sırası önemsiz
@onbellekle()
def kw(a,b=1,c=2): return a+b+c
assert kw(1,b=2,c=3) == 6
assert kw(1,c=3,b=2) == 6  # aynı sonucu vermeli, isabet olmalı
assert kw.bilgi() == {'isabet':1,'iska':1}
print('Kwargs sırası:', kw.bilgi())

# 6. temizle() sadece kendi önbelleğini temizlemeli, sayaçları sıfırlamalı
@onbellekle()
def clear_test(x): return x
clear_test(1); clear_test(1)
assert clear_test.bilgi() == {'isabet':1,'iska':1}
clear_test.temizle()
assert clear_test.bilgi() == {'isabet':0,'iska':0}
print('Temizle:', clear_test.bilgi())

# 7. __name__ ve __doc__ korunmalı
@onbellekle()
def doc_test(x): '''Belge metni'''; return x
assert doc_test.__name__ == 'doc_test'
assert doc_test.__doc__ == 'Belge metni'
print('Name/Doc:', doc_test.__name__, doc_test.__doc__)

print('\nTÜM GİZLİ TESTLER GEÇTİ')

